@push('scripts')<script>(function(){const modal=new bootstrap.Modal('#discount-modal'),f=document.querySelector('#discount-form'),table=$('#discounts-table').DataTable({processing:true,serverSide:true,ajax:'{{route('tenant.discounts.listing')}}',columns:[{data:'name'},{data:'code'},{data:'discount_type'},{data:'value'},{data:'is_active',render:v=>v?'Active':'Inactive'},{data:'id',orderable:false,render:id=>`<button class="btn btn-sm edit" data-id="${id}">Edit</button> <button class="btn btn-sm text-danger del" data-id="${id}">Delete</button>`}]});document.querySelector('#new-discount')?.addEventListener('click',()=>{f.reset();f.id.value='';modal.show()});$('#discounts-table').on('click','.edit',e=>fetch('{{url('tenant/discounts')}}/'+e.currentTarget.dataset.id).then(r=>r.json()).then(d=>{Object.keys(d).forEach(k=>{if(f[k])f[k].value=d[k]??''});modal.show()}));f.addEventListener('submit',e=>{e.preventDefault();fetch('{{route('tenant.discounts.save')}}',{method:'POST',headers:{'X-CSRF-TOKEN':'{{csrf_token()}}','Accept':'application/json'},body:new FormData(f)}).then(async r=>{let d=await r.json();if(!r.ok)throw d;Swal.fire({icon:'success',text:d.message});modal.hide();table.ajax.reload(null,false)}).catch(d=>Swal.fire({icon:'error',text:d.message||'Validation failed.'}))});$('#discounts-table').on('click','.del',e=>Swal.fire({icon:'warning',text:'Delete this discount?',showCancelButton:true}).then(x=>{if(x.isConfirmed)fetch('{{url('tenant/discounts')}}/'+e.currentTarget.dataset.id,{method:'DELETE',headers:{'X-CSRF-TOKEN':'{{csrf_token()}}','Accept':'application/json'}}).then(r=>r.json()).then(d=>{Swal.fire({icon:'success',text:d.message});table.ajax.reload(null,false)})}))})();</script>@endpush
